CREATE TABLE district (district_id int, name text, region text, num_inhabitants int, avg_salary float, unemp_95 float, unemp_96 float);
CREATE TABLE loan (loan_id int, account_id int, date date, amount float, duration int, payments float, status text);
CREATE TABLE order_list (order_id int, account_id int, bank_to text, account_to int, amount float, k_symbol text);

Evidence: 'Good loan status' is defined as status IN ('A', 'B') where contracts finished or running OK; 'Defaulted loan' is defined as status IN ('C', 'D'). Operation 'VYBER' denotes cash withdrawal.
Question: What is the total withdrawal amount in 1996 for accounts whose owners took out defaulted loans?
Gold SQL: SELECT SUM(T1.amount) FROM trans AS T1 JOIN loan AS T2 ON T1.account_id = T2.account_id WHERE T1.operation = 'VYBER' AND strftime('%Y', T1.date) = '1996' AND T2.status IN ('C', 'D')

